const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu')}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();menu.focus()}});
nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});let shown=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=b.dataset.filter!=='all'&&card.dataset.category!==b.dataset.filter&&b.dataset.filter!=='brand';if(!card.hidden)shown++});document.querySelector('.empty').hidden=shown>0}));
const form=document.querySelector('#project-form');
if(form){form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const keys=['Name','Email','Company','Website','Services','Problem','Success','Timing','Budget'];const message=keys.map(k=>k+': '+(data.getAll(k).join(', ')||'Not specified')).join('\n\n');document.querySelector('#draft').value=message;document.querySelector('#email-fallback').hidden=false;document.querySelector('#form-status').textContent='Your enquiry is ready. Send it from your email app to start the conversation.';location.href='mailto:hello@ignitia.digital?subject='+encodeURIComponent('Project enquiry — '+data.get('Name'))+'&body='+encodeURIComponent(message)});document.querySelector('#copy-draft').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#draft').value);document.querySelector('#form-status').textContent='Enquiry copied. Paste it into your email to hello@ignitia.digital.'}catch{document.querySelector('#draft').select();document.querySelector('#form-status').textContent='Select and copy the enquiry below.'}})}
